-6"><label class="form-label fw-semibold">Ciclo</label><select name="cycle_id" class="form-select" required><option value="">Seleccione</option><?php foreach($cycles as $cycle): ?><option value="<?= (int)$cycle['id'] ?>"><?= htmlspecialchars($cycle['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label fw-semibold">Semestre</label><select name="semester_id" class="form-select" required><option value="">Seleccione</option><?php foreach($semesters as $semester): ?><option value="<?= (int)$semester['id'] ?>"><?= htmlspecialchars($semester['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label fw-semibold">Turno</label><select name="shift" class="form-select" required><option value="manana">Mañana</option><option value="tarde">Tarde</option></select></div><div class="col-12"><label class="form-label fw-semibold">Fotografía</label><input type="file" name="photo" class="form-control" accept="image/jpeg,image/png,image/webp"><div class="form-text">JPG, PNG o WEBP. Máximo 3 MB.</div></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar estudiante</button></div></form></div></div></div>
<div class="modal fade" id="cardModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content border-0"><div class="modal-header"><h5 class="modal-title fw-bold"><i class="bi bi-person-vcard me-2 text-primary"></i>Carnet digital del estudiante</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body py-4"><article class="credential" id="printableArea"><header class="credential-head"><div><div class="institute-name">INSTITUTO</div><div class="credential-title">CARNET DE ESTUDIANTE</div></div><img src="assets/img/logo-jsc-hd.png" alt="Logo IES José Santos Chocano"></header><div class="credential-body"><div id="photoFallback" class="credential-photo credential-photo-placeholder d-flex align-items-center justify-content-center"><i class="bi bi-person"></i><span>Sin fotografía</span></div><img id="cardPhoto" class="credential-photo d-none" alt="Fotografía del estudiante"><div class="credential-data"><span class="credential-label">Apellidos y nombres</span><span id="cardName" class="credential-value"></span><span class="credential-label">Especialidad</span><div id="cardSpecialty" class="specialty mb-2"></div><span class="credential-label">Ciclo</span><span id="cardCycle" class="credential-value"></span><span class="credential-label">Semestre</span><span id="cardSemester" class="credential-value"></span><span class="credential-label">Documento</span><span id="cardDni" class="credential-value mb-0"></span></div><div class="credential-side"><img id="cardQr" class="credential-qr" alt="Código QR"><div id="cardCode" class="credential-number font-monospace fw-bold mt-2"></div><div class="credential-note">CÓDIGO DE ACCESO</div></div></div></article></div><div class="modal-footer"><button class="btn btn-primary" onclick="document.title='Carnet_'+document.getElementById('cardName').textContent.trim().replaceAll(' ','_');window.print()"><i class="bi bi-printer me-1"></i> Imprimir o guardar PDF</button></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script><script>function selectedStudentIds(){return [...document.querySelectorAll('.student-card-check:checked:not(:disabled)')].map(check=>check.value)}function appendSelectedStudents(target,asQuery){selectedStudentIds().forEach(id=>{if(asQuery)target.append('ids[]',id);else{const input=document.createElement('input');input.type='hidden';input.name='ids[]';input.value=id;target.appendChild(input)}})}function exportFilteredReport(sourceForm){const exportForm=document.createElement('form');exportForm.method='POST';exportForm.action='?c=Employee&a=export';const data=new FormData(sourceForm);data.delete('c');for(const [name,value] of data){const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;exportForm.appendChild(input)}appendSelectedStudents(exportForm,false);document.body.appendChild(exportForm);exportForm.submit();exportForm.remove()}function exportFilteredCards(sourceForm,format){const data=new FormData(sourceForm),params=new URLSearchParams();for(const [name,value] of data){if(name!=='c'&&value)params.set(name,value)}appendSelectedStudents(params,true);params.set('c','Employee');params.set('a','cards');params.set('download',format);window.open('?'+params.toString(),'_blank','noopener')}function updateSelectedCards(){const checks=[...document.querySelectorAll('.student-card-check:not(:disabled)')],selected=checks.filter(check=>check.checked),all=document.getElementById('selectAllStudents'),count=document.getElementById('selectedCardsCount');count.textContent=selected.length?selected.length:'Todos';all.checked=checks.length>0&&selected.length===checks.length;all.indeterminate=selected.length>0&&selected.length<checks.length}document.addEventListener('DOMContentLoaded',()=>{const all=document.getElementById('selectAllStudents');all.addEventListener('change',()=>{document.querySelectorAll('.student-card-check:not(:disabled)').forEach(check=>check.checked=all.checked);updateSelectedCards()});document.querySelectorAll('.student-card-check').forEach(check=>check.addEventListener('change',updateSelectedCards));updateSelectedCards()});function showCard(button){const s=JSON.parse(button.dataset.student);document.getElementById('cardName').textContent=s.name;document.getElementById('cardSpecialty').textContent=s.specialty;document.getElementById('cardCycle').textContent=s.cycle;document.getElementById('cardSemester').textContent=s.semester;document.getElementById('cardDni').textContent='DNI: '+s.dni;document.getElementById('cardCode').textContent=s.code;document.getElementById('cardQr').src='?c=Employee&a=qr&code='+encodeURIComponent(s.code);const p=document.getElementById('cardPhoto'),f=document.getElementById('photoFallback');p.classList.toggle('d-none',!s.photo);f.classList.toggle('d-none',!!s.photo);if(s.photo)p.src=s.photo;bootstrap.Modal.getOrCreateInstance(document.getElementById('cardModal')).show()}</script></body></html>
